-- ==============================================================================
-- TABLA 2: PLATOS Y PRODUCTOS (products) - 100% LIMPIA Y SIN CAMPOS INNECESARIOS
-- BuchiSapa Burger & Broaster - 57 Platos Oficiales
-- ==============================================================================

-- 1. Eliminar columnas que no se usan si ya habías creado la tabla:
ALTER TABLE IF EXISTS public.products DROP COLUMN IF EXISTS code;
ALTER TABLE IF EXISTS public.products DROP COLUMN IF EXISTS category_code;
ALTER TABLE IF EXISTS public.products DROP COLUMN IF EXISTS badge;
ALTER TABLE IF EXISTS public.products DROP COLUMN IF EXISTS original_price;
ALTER TABLE IF EXISTS public.products DROP COLUMN IF EXISTS popular;

-- 2. Definicion limpia de la tabla
CREATE TABLE IF NOT EXISTS public.products (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    category_id TEXT REFERENCES public.categories(id) ON DELETE SET NULL,
    category TEXT,
    price NUMERIC(10,2) NOT NULL DEFAULT 0,
    description TEXT,
    available BOOLEAN DEFAULT true,
    stock INTEGER DEFAULT 50,
    image TEXT,
    includes_sauces BOOLEAN DEFAULT false,
    accompaniments JSONB DEFAULT '[]'::jsonb,
    cremas JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_products_category ON public.products(category_id);

ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Productos publicos" ON public.products;
CREATE POLICY "Productos publicos" ON public.products FOR ALL USING (true);

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, stock = EXCLUDED.stock, available = EXCLUDED.available, image = EXCLUDED.image, accompaniments = EXCLUDED.accompaniments, cremas = EXCLUDED.cremas;
